#!/bin/bashset -e# Check if virtual environment existsif [ ! -d "./venv" ]; then    echo "Creating virtual environment..."    python3 -m venv venvfi# Activate virtual environmentecho "Activating virtual environment..."source venv/bin/activate# Install dependenciesif [ -f "requirements.txt" ]; then    echo "Installing dependencies from requirements.txt..."    pip install --no-cache-dir -r requirements.txtfi# Run the FastAPI applicationecho "Starting FastAPI application..."uvicorn app.main:app --host 0.0.0.0 --port 8000 --reload